/**
 * Request to move a lifecycle to another state.
 */
export interface AssetTransitionRequest {
  /**
   * The state the caller believes the row is in (compare-and-set).
   * Pattern: `^[A-Z][A-Za-z]*( [A-Z][A-Za-z]*)*$`.
   */
  readonly expected_state: string;
  /**
   * Target state.
   * Pattern: `^[A-Z][A-Za-z]*( [A-Z][A-Za-z]*)*$`.
   */
  readonly to_state: string;
  /**
   * Reason, required by some transitions.
   * Length: 1 to unbounded.
   */
  readonly reason?: string;
}

/**
 * A scanned code.
 */
export interface ScanRequest {
  /**
   * Scanned barcode, QR or NFC payload.
   * Length: 1 to unbounded.
   */
  readonly code: string;
  /**
   * Symbology of the scan.
   * Length: 1 to unbounded.
   */
  readonly symbology: string;
}

/**
 * The outcome of one scan event.
 */
export interface AssetScanResult {
  /**
   * applied for a new event; duplicate when the event id was already applied.
   */
  readonly outcome: "applied" | "duplicate";
  /**
   * What the code named.
   */
  readonly subject_kind: "unit" | "lot";
  /**
   * The asset unit or lot moved.
   * Format: `uuid`.
   */
  readonly subject_id: string;
  /**
   * The custody entry or lot movement, equal to the event id.
   * Format: `uuid`.
   */
  readonly ledger_id: string;
  /**
   * Units: the state after the move.
   */
  readonly asset_state:
    | "Proposed"
    | "Received"
    | "Available"
    | "Reserved"
    | "Deployed"
    | "In Maintenance"
    | "Damaged"
    | "Lost"
    | "Retired"
    | null;
  /**
   * Lots: the quantity on hand after the move.
   */
  readonly on_hand: number | null;
}

/**
 * One custody move scanned on a device.
 */
export interface AssetScanEvent {
  /**
   * UUID the device minted when the scan happened and keeps in its offline queue. It becomes the custody entry or lot movement id, so replaying the event at any later time changes nothing.
   * Format: `uuid`.
   */
  readonly event_id: string;
  /**
   * The scanned asset tag, external identifier (serial, GTIN) or lot label (LOT:<lot id>).
   * Length: 1 to 200.
   */
  readonly code: string;
  /**
   * check-out hands the item to one custodian (the unit becomes Deployed); check-in returns it to a venue (the unit becomes Available); transfer passes a deployed unit to another custodian.
   */
  readonly action: "check-out" | "check-in" | "transfer";
  /**
   * Identifier of the member who takes the item.
   * Format: `uuid`.
   */
  readonly custodian_membership_id?: string | null;
  /**
   * Identifier of the external engagement that takes the item; never together with a member.
   * Format: `uuid`.
   */
  readonly custodian_engagement_id?: string | null;
  /**
   * Identifier of the venue the item returns to; the unit's home venue by default.
   * Format: `uuid`.
   */
  readonly venue_id?: string | null;
  /**
   * Identifier of the project the item is out for.
   * Format: `uuid`.
   */
  readonly project_id?: string | null;
  /**
   * Hand-over note.
   * Length: 0 to 1000.
   */
  readonly note?: string | null;
  /**
   * Lots only: how many move.
   */
  readonly quantity?: number | null;
}

/**
 * What a bulk change of asset units did, or would do in a preview.
 */
export interface AssetUnitBulkEditResult {
  /**
   * True for a preview, which never changes anything.
   */
  readonly preview: boolean;
  /**
   * True only when every row passed and the change was applied. Any refused row means nothing changed.
   */
  readonly committed: boolean;
  /**
   * Rows the change alters, or would alter in a preview.
   * Range: 0 to unbounded.
   */
  readonly changed: number;
  /**
   * Rows that already hold the values.
   * Range: 0 to unbounded.
   */
  readonly unchanged: number;
  /**
   * Rows that cannot change, each with its rule; empty when every row passed.
   */
  readonly refused: ReadonlyArray<BulkEditRefusal>;
  /**
   * Rows that undo a committed change: the values before as `set` and the values written as `expect`. Empty for a preview or a refused change.
   */
  readonly inverse: ReadonlyArray<AssetUnitBulkRow>;
}

/**
 * One of the asset units in a bulk change: the values to `set` and, optionally, the values the caller saw (`expect`, compare-and-set). A row whose current value differs from `expect` is refused as bulk_stale; an instant matches in any ISO 8601 form with an offset (Z or +00:00).
 */
export interface AssetUnitBulkRow {
  /**
   * Row to change.
   * Format: `uuid`.
   */
  readonly id: string;
  readonly set: AssetUnitBulkValues;
  readonly expect?: AssetUnitBulkValues;
}

/**
 * Fields of one of the asset units in a bulk change. Only these fields change in bulk.
 */
export interface AssetUnitBulkValues {
  /**
   * Asset lifecycle state.
   */
  readonly asset_state?:
    | "Proposed"
    | "Received"
    | "Available"
    | "Reserved"
    | "Deployed"
    | "In Maintenance"
    | "Damaged"
    | "Lost"
    | "Retired";
  /**
   * Venue the unit returns to.
   * Format: `uuid`.
   */
  readonly home_venue_id?: string | null;
  /**
   * Condition: a row of the canon Asset Condition enumeration.
   * Pattern: `^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$`.
   */
  readonly condition_enum_id?: string | null;
}

/**
 * A bulk change of asset units.
 */
export interface AssetUnitBulkEditRequest {
  /**
   * The rows to change, each once; at most 500.
   */
  readonly rows: ReadonlyArray<AssetUnitBulkRow>;
  /**
   * Why: recorded as the reason of every state change and in the audit event, and as the replan reason where a moved date needs one.
   * Length: 1 to 500.
   */
  readonly reason?: string;
}

