/**
 * A document and asset library entry. Standard Library row, copied into each new org as editable org data.
 */
export interface StdDocument {
  readonly record_id: StdCode;
  /**
   * Document name.
   * Length: 1 to 500.
   */
  readonly document_name: string | null;
  /**
   * Document type.
   * Length: 1 to 200.
   */
  readonly document_type: string | null;
  /**
   * Reference identifier.
   * Length: 1 to 200.
   */
  readonly reference_id: string | null;
  /**
   * File format.
   * Length: 1 to 100.
   */
  readonly file_format: string | null;
  /**
   * Version.
   * Length: 1 to 100.
   */
  readonly version: string | null;
  /**
   * Issue date.
   * Format: `date`.
   */
  readonly issue_date: string | null;
  /**
   * Expiration date.
   * Format: `date`.
   */
  readonly expiration_date: string | null;
  /**
   * Department as the sheet names it.
   * Length: 1 to 200.
   */
  readonly department: string | null;
  /**
   * Category code or name as the sheet gives it.
   * Length: 1 to 200.
   */
  readonly category: string | null;
  /**
   * Sub-category as the sheet names it.
   * Length: 1 to 200.
   */
  readonly sub_category: string | null;
  /**
   * Row status in the sheet.
   * Length: 1 to 200.
   */
  readonly status: string | null;
  /**
   * Notes in the sheet.
   * Length: 1 to 20000.
   */
  readonly notes: string | null;
  /**
   * Organization as the sheet names it.
   * Length: 1 to 200.
   */
  readonly organization: string | null;
  /**
   * Project as the sheet names it.
   * Length: 1 to 200.
   */
  readonly project: string | null;
  /**
   * File size as the sheet gives it.
   * Length: 1 to 100.
   */
  readonly file_size: string | null;
  /**
   * Where the file is stored, as the sheet gives it.
   * Length: 1 to 2000.
   */
  readonly storage_url: string | null;
}

