/**
 * One party acting for another, with scopes and expiry. The artist accepts it.
 */
export interface Representation {
  /**
   * Identifier of the representation.
   * Format: `uuid`.
   */
  readonly id: string;
  /**
   * When the row was created.
   * Format: `date-time`.
   */
  readonly created_at: string;
  /**
   * When the row was last updated.
   * Format: `date-time`.
   */
  readonly updated_at: string;
  /**
   * Identifier of the representative.
   * Format: `uuid`.
   */
  readonly representative_person_id: string | null;
  /**
   * Identifier of the represented artist.
   * Format: `uuid`.
   */
  readonly artist_person_id: string;
  /**
   * Delegated scopes, stored as junction rows.
   */
  readonly scopes: ReadonlyArray<RepresentationScope>;
  /**
   * Expiry.
   * Format: `date`.
   */
  readonly expires_on: string;
  /**
   * When the artist accepted.
   * Format: `date-time`.
   */
  readonly accepted_at: string | null;
  /**
   * When the artist or the account revoked it.
   * Format: `date-time`.
   */
  readonly revoked_at: string | null;
}

/**
 * Scope a representation delegates.
 */
export type RepresentationScope = "Offers" | "Advance" | "Settlement" | "Documents";

/**
 * Fields accepted when creating a Representation.
 */
export interface RepresentationCreate {
  /**
   * Identifier of the representative.
   * Format: `uuid`.
   */
  readonly representative_person_id?: string | null;
  /**
   * Identifier of the represented artist.
   * Format: `uuid`.
   */
  readonly artist_person_id: string;
  /**
   * Delegated scopes, stored as junction rows.
   */
  readonly scopes: ReadonlyArray<RepresentationScope>;
  /**
   * Expiry.
   * Format: `date`.
   */
  readonly expires_on: string;
}

