/**
 * An email invitation to join an org. Created through `invites.create` (the `app.invite_member` RPC); the token is never stored or returned again.
 */
export interface Invite {
  /**
   * Identifier of the invite.
   * Format: `uuid`.
   */
  readonly id: string;
  /**
   * Identifier of the owning organization, derived from the parent row and never accepted from the caller.
   * Format: `uuid`.
   */
  readonly org_id: string;
  /**
   * When the row was created.
   * Format: `date-time`.
   */
  readonly created_at: string;
  /**
   * Identifier of the person who created the row; null when a seed, platform or system process created it.
   * Format: `uuid`.
   */
  readonly created_by: string | null;
  /**
   * When the row was last updated.
   * Format: `date-time`.
   */
  readonly updated_at: string;
  /**
   * Identifier of the person who last updated the row; null when a seed, platform or system process updated it.
   * Format: `uuid`.
   */
  readonly updated_by: string | null;
  /**
   * Invitee email.
   * Format: `email`.
   */
  readonly email: string;
  /**
   * Identifier of the role offered.
   * Format: `uuid`.
   */
  readonly role_id: string;
  /**
   * When the invite expires.
   * Format: `date-time`.
   */
  readonly expires_at: string;
  /**
   * Identifier of the inviting person.
   * Format: `uuid`.
   */
  readonly invited_by: string;
  /**
   * When it was accepted.
   * Format: `date-time`.
   */
  readonly accepted_at: string | null;
  /**
   * When it was revoked or replaced.
   * Format: `date-time`.
   */
  readonly revoked_at: string | null;
  /**
   * True for the first Owner invite a partner issues when it creates a client org (Section 4.6.1).
   */
  readonly partner_bootstrap: boolean;
  /**
   * Identifier of the person who accepted.
   * Format: `uuid`.
   */
  readonly accepted_person_id: string | null;
}

/**
 * The created invite. The token is shown once; only its hash is stored.
 */
export interface InviteMemberResult {
  /**
   * Identifier of the invite.
   * Format: `uuid`.
   */
  readonly invite_id: string;
  /**
   * Invite token from the invitation email. Sent in the body, never in a URL.
   * Length: 1 to unbounded.
   */
  readonly invite_token: string;
}

/**
 * Invites an email to the caller's organization, replacing any pending invite for it.
 */
export interface InviteMemberRequest {
  /**
   * Invitee email.
   * Format: `email`.
   */
  readonly email: string;
  /**
   * Identifier of the role offered, at or below the inviter's band.
   * Format: `uuid`.
   */
  readonly role_id: string;
  /**
   * Hours until the invite expires, from 1 to 720. Default 336 (14 days).
   * Range: 1 to 720.
   */
  readonly valid_for_hours?: number;
}

/**
 * What an invite offers, shown only to its confirmed recipient.
 */
export interface InvitePreview {
  /**
   * Organization the invite joins.
   * Length: 1 to 300.
   */
  readonly org_name: string;
  /**
   * Offered role code.
   * Pattern: `^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$`.
   */
  readonly role_code: string;
  /**
   * Offered role name.
   * Length: 1 to 300.
   */
  readonly role_name: string;
  /**
   * When the invite expires.
   * Format: `date-time`.
   */
  readonly expires_at: string;
}

/**
 * An invite token presented by its recipient.
 */
export interface InviteTokenRequest {
  /**
   * Invite token from the invitation email. Sent in the body, never in a URL.
   * Length: 1 to unbounded.
   */
  readonly token: string;
}

/**
 * The membership the accepted invite joined.
 */
export interface AcceptInviteResult {
  /**
   * Identifier of the membership joined or reused.
   * Format: `uuid`.
   */
  readonly membership_id: string;
}

