/**
 * A verified email domain with automatic join and a default role.
 */
export interface VerifiedDomain {
  /**
   * Identifier of the verified domain.
   * Format: `uuid`.
   */
  readonly id: string;
  /**
   * Identifier of the owning organization, derived from the parent row and never accepted from the caller.
   * Format: `uuid`.
   */
  readonly org_id: string;
  /**
   * When the row was created.
   * Format: `date-time`.
   */
  readonly created_at: string;
  /**
   * Identifier of the person who created the row; null when a seed, platform or system process created it.
   * Format: `uuid`.
   */
  readonly created_by: string | null;
  /**
   * When the row was last updated.
   * Format: `date-time`.
   */
  readonly updated_at: string;
  /**
   * Identifier of the person who last updated the row; null when a seed, platform or system process updated it.
   * Format: `uuid`.
   */
  readonly updated_by: string | null;
  /**
   * Lowercase host name, for example gateway.northwindlive.example.
   * Length: 1 to 253.
   */
  readonly hostname: string;
  /**
   * What the domain is for.
   */
  readonly purpose: "Atlas" | "Gateway" | "Email Sending" | "Verified Domain";
  /**
   * DNS verification state; changed only by app.record_domain_verification.
   */
  readonly verification_state: "Pending" | "Verified" | "Failed";
  /**
   * Value the org publishes in a DNS TXT record to prove control.
   * Length: 1 to 300.
   */
  readonly verification_token: string;
  /**
   * When the verification service last checked DNS.
   * Format: `date-time`.
   */
  readonly last_checked_at: string | null;
  /**
   * Identifier of the role a person with a confirmed address at this verified domain receives on joining automatically; null turns automatic join off.
   * Format: `uuid`.
   */
  readonly auto_join_role_id: string | null;
  /**
   * Where the domain stands at its provider.
   */
  readonly provisioning_status:
    "Not Started" | "Requested" | "Pending DNS" | "Active" | "Failed" | "Released";
  /**
   * DNS records to publish for the provider.
   */
  readonly dns_records: ReadonlyArray<DomainDnsRecord>;
  /**
   * True once the provider issued the TLS certificate.
   */
  readonly tls_ready: boolean;
  /**
   * Why the latest provisioning step failed.
   * Length: 1 to 2000.
   */
  readonly provisioning_error: string | null;
}

/**
 * A DNS record the org publishes for a custom domain's provider.
 */
export interface DomainDnsRecord {
  /**
   * DNS record type.
   * Length: 1 to 10.
   */
  readonly type: string;
  /**
   * Host the record is published at.
   * Length: 1 to 253.
   */
  readonly name: string;
  /**
   * Record value.
   * Length: 1 to 2000.
   */
  readonly value: string;
  /**
   * What the record is for: routing, verification, spf, dkim, dmarc or receiving.
   * Length: 1 to 20.
   */
  readonly purpose: string;
}

/**
 * Fields accepted when creating a VerifiedDomain.
 */
export interface VerifiedDomainCreate {
  /**
   * Lowercase host name, for example gateway.northwindlive.example.
   * Length: 1 to 253.
   */
  readonly hostname: string;
  /**
   * What the domain is for.
   */
  readonly purpose: "Atlas" | "Gateway" | "Email Sending" | "Verified Domain";
  /**
   * Identifier of the role a person with a confirmed address at this verified domain receives on joining automatically; null turns automatic join off.
   * Format: `uuid`.
   */
  readonly auto_join_role_id?: string | null;
}

/**
 * Fields accepted when updating a VerifiedDomain. Omitted fields are unchanged.
 */
export interface VerifiedDomainUpdate {
  /**
   * Identifier of the role a person with a confirmed address at this verified domain receives on joining automatically; null turns automatic join off.
   * Format: `uuid`.
   */
  readonly auto_join_role_id?: string | null;
}

