/**
 * A person's profile page, owned by the person. New profiles start Private.
 */
export interface PersonProfile {
  /**
   * Identifier of the person profile.
   * Format: `uuid`.
   */
  readonly id: string;
  /**
   * When the row was created.
   * Format: `date-time`.
   */
  readonly created_at: string;
  /**
   * When the row was last updated.
   * Format: `date-time`.
   */
  readonly updated_at: string;
  /**
   * Identifier of the person.
   * Format: `uuid`.
   */
  readonly person_id: string;
  /**
   * Headline.
   * Length: 1 to 300.
   */
  readonly headline: string | null;
  /**
   * Bio.
   * Length: 1 to 20000.
   */
  readonly bio: string | null;
  /**
   * Pronouns, optional.
   * Length: 1 to 300.
   */
  readonly pronouns: string | null;
  /**
   * City.
   * Length: 1 to 300.
   */
  readonly locality: string | null;
  /**
   * ISO 3166-1 alpha-2 country code.
   * Pattern: `^[A-Z]{2}$`.
   */
  readonly country: string | null;
  readonly visibility: ProfileVisibility;
  /**
   * Whether search engines may index a public profile.
   */
  readonly search_indexing: boolean;
  /**
   * Unique handle for /u/{handle} or /c/{handle}: 3 to 40 lowercase letters, digits and single hyphens. Changeable once every 30 days; the old handle redirects for 90 days.
   * Pattern: `^[a-z0-9]([a-z0-9-]{1,38}[a-z0-9])$`.
   */
  readonly handle: string;
  /**
   * When the handle last changed; null until the first change. Set by the database.
   * Format: `date-time`.
   */
  readonly handle_changed_at: string | null;
  /**
   * Name the person goes by.
   * Length: 1 to 100.
   */
  readonly preferred_name: string | null;
}

/**
 * Profile visibility. Sections and fields may be set lower than the profile, never higher.
 */
export type ProfileVisibility = "Public" | "Network" | "Private";

