  /**
   * Currency of the partner agreement.
   * Pattern: `^[A-Z]{3}$`.
   */
  readonly currency_code: string;
  /**
   * Discount in basis points when the statement ran; agreements default to 3000, the 30 percent of ADR 0035.
   * Range: 0 to unbounded.
   */
